/* Scoped additive World Nation skills. Restore exact prior flags on context exit. */
typedef struct {uptr id;u32 bits[3],active;} WorldSkills;
static WorldSkills world_skills[65536];static volatile unsigned char world_lock;
static void world_take(void){while(__atomic_test_and_set(&world_lock,__ATOMIC_ACQUIRE)){} }static void world_drop(void){__atomic_clear(&world_lock,__ATOMIC_RELEASE);}
static WorldSkills*world_row(uptr id,int create){u32 slot=(u32)(id^(id>>32))&65535;for(u32 n=0;n<65536;n++,slot=(slot+1)&65535){WorldSkills*r=&world_skills[slot];if(r->id==id)return r;if(!r->id){if(create)r->id=id;return create?r:0;}}return 0;}
static void world_restore(void*p,uptr id){world_take();WorldSkills*r=world_row(id,0);if(r&&r->active){for(u32 i=0;i<74;i++)if((r->bits[i/32]>>(i%32))&1)set_parameter(p,70+i,0);r->active=0;}world_drop();}
static void world_add(void*p,WorldSkills*r,u32 flag){u32 old=0;if(get_parameter(p,flag,&old)&&!old){r->bits[(flag-70)/32]|=1u<<((flag-70)%32);set_parameter(p,flag,1);}}
static void world_apply(void*p,uptr id){if(active_competition!=128)return;world_take();WorldSkills*r=world_row(id,1);if(!r){world_drop();return;}for(u32 i=0;i<3;i++)r->bits[i]=0;r->active=1;u32 role=0;get_parameter(p,0,&role);switch(role){case 0:{static const u32 f[]={100,126,129,88,90,105,95,97};for(u32 i=0;i<sizeof(f)/sizeof(f[0]);i++)world_add(p,r,f[i]);break;}case 1:{static const u32 f[]={115,123,125,111,112,106,113,94,97,128};for(u32 i=0;i<sizeof(f)/sizeof(f[0]);i++)world_add(p,r,f[i]);break;}case 2:{static const u32 f[]={119,117,122,84,85,87,106,125,111,97};for(u32 i=0;i<sizeof(f)/sizeof(f[0]);i++)world_add(p,r,f[i]);break;}case 3:{static const u32 f[]={119,117,122,84,85,87,106,125,111,97};for(u32 i=0;i<sizeof(f)/sizeof(f[0]);i++)world_add(p,r,f[i]);break;}case 4:{static const u32 f[]={117,118,122,131,82,110,83,87,85,130,124,97,128,115,125,111,106};for(u32 i=0;i<sizeof(f)/sizeof(f[0]);i++)world_add(p,r,f[i]);break;}case 5:{static const u32 f[]={117,118,122,131,82,110,83,87,85,130,124,97,128};for(u32 i=0;i<sizeof(f)/sizeof(f[0]);i++)world_add(p,r,f[i]);break;}case 6:{static const u32 f[]={116,124,130,135,119,120,117,122,131,134,127,82,110,97};for(u32 i=0;i<sizeof(f)/sizeof(f[0]);i++)world_add(p,r,f[i]);break;}case 7:{static const u32 f[]={116,124,130,135,119,120,117,122,131,134,127,82,110,97};for(u32 i=0;i<sizeof(f)/sizeof(f[0]);i++)world_add(p,r,f[i]);break;}case 8:{static const u32 f[]={117,118,122,131,82,110,83,87,85,130,124,97,128};for(u32 i=0;i<sizeof(f)/sizeof(f[0]);i++)world_add(p,r,f[i]);break;}case 9:{static const u32 f[]={116,124,130,135,119,120,117,122,131,134,127,82,110,97};for(u32 i=0;i<sizeof(f)/sizeof(f[0]);i++)world_add(p,r,f[i]);break;}case 10:{static const u32 f[]={116,124,130,135,119,120,117,122,131,134,127,82,110,97};for(u32 i=0;i<sizeof(f)/sizeof(f[0]);i++)world_add(p,r,f[i]);break;}case 11:{static const u32 f[]={114,121,134,127,124,128,116,130,120,76,81,79,82,110,97};for(u32 i=0;i<sizeof(f)/sizeof(f[0]);i++)world_add(p,r,f[i]);break;}case 12:{static const u32 f[]={114,121,134,127,124,128,116,130,120,76,81,79,82,110,97};for(u32 i=0;i<sizeof(f)/sizeof(f[0]);i++)world_add(p,r,f[i]);break;}}world_drop();}
